// Kart destesinin saf mantığı: son dört hane güvenliği, deste konumu, ok tuşuyla dönme ve yazımlar.
// Bu bir görünümdür: gerçek kart numarası hiçbir yerde tutulmaz ya da gösterilmez, yalnız son dört hane. Para TRY'dir; hesap kuruş tamsayısıyla yapılır.
import { exactText, signedMinorText, toMinor, countText } from "../lib/shop-format";

export type CardMaterial = "metal" | "black" | "glass" | "flat";

export interface CardTransaction { id: string; merchant: string; detail?: string | undefined; /** Ana birimde TRY; çıkan eksi. */ amount: number }
export interface WalletCard {
  id: string;
  issuer: string;
  product: string;
  /** Yalnız son dört hane. Daha uzun bir metin verilirse yine son dört hane alınır, kalanı atılır. */
  last4: string;
  holder: string;
  /** "AA/YY" biçimli son kullanma; geçersizse "—" yazılır. */
  expiry: string;
  /** Kurgusal ağ adı; gerçek marka işareti konmaz. */
  network?: string | undefined;
  material?: CardMaterial | undefined;
  /** Kullanılabilir bakiye (ana birimde TRY). */
  balance: number;
  transactions: CardTransaction[];
}

/** Güvenlik: verilen metinden yalnız rakamlar alınır ve yalnız son dört hane döner. Dört haneden az varsa eksik haneler nokta olur. */
export function safeLast4(raw: string): string {
  const digits = raw.replace(/\D/g, "");
  return digits.length >= 4 ? digits.slice(-4) : digits.padStart(4, "•");
}

/** Görsel numara: "•••• •••• •••• 0417". */
export const maskedNumber = (raw: string): string => `•••• •••• •••• ${safeLast4(raw)}`;

/** Son kullanma "AA/YY" biçiminde ve ay 01–12 ise olduğu gibi, değilse "—". */
export function expiryText(raw: string): string {
  return /^(0[1-9]|1[0-2])\/\d{2}$/.test(raw.trim()) ? raw.trim() : "—";
}

export const MAX_CARDS = 6;
/** Deste en çok `MAX_CARDS` kart çizer (her kart çizildiğinden sınırlıdır). */
export const visibleCards = <T,>(cards: T[]): T[] => cards.slice(0, MAX_CARDS);

export interface Place { y: number; scale: number; opacity: number; hidden: boolean }

/**
 * Bir kartın deste konumu: `pos` kartın öndekine göre sırası (0 ön, 1 bir arkada...), `open` 0–1 arası açıklık (üstüne gelince deste açılır).
 * Önde olanı geçmiş kartlar (`pos` < 0) aşağı kayıp saydamlaşır; ilk üç arka kart görünür. `y` karta oranla, yukarı eksi.
 */
export function placeOf(pos: number, open: number, peek = .12): Place {
  if (pos < 0) return { y: 1.15, scale: 1, opacity: 0, hidden: true };
  const spread = 1 + open * .9;
  const hidden = pos > 3;
  return { y: -pos * peek * spread, scale: Math.max(.8, 1 - pos * .04), opacity: hidden ? 0 : 1 - Math.max(0, pos - 2) * .6, hidden };
}

/** Ok tuşları: aşağı/sağ ileri, yukarı/sol geri, Home/End ilk-son; uçlarda yerinde kalır. */
export function stepFront(key: string, front: number, count: number): number {
  const last = count - 1;
  if (key === "ArrowDown" || key === "ArrowRight") return Math.min(last, front + 1);
  if (key === "ArrowUp" || key === "ArrowLeft") return Math.max(0, front - 1);
  if (key === "Home") return 0;
  if (key === "End") return last;
  return front;
}

/** Sürükleme sonucu: aşağı çekmek ileri (1), yukarı çekmek geri (-1). */
export function dragStep(offsetY: number, velocityY: number): -1 | 0 | 1 {
  if (offsetY > 60 || velocityY > 500) return 1;
  if (offsetY < -60 || velocityY < -500) return -1;
  return 0;
}

export const cardLabel = (card: WalletCard, index: number, count: number): string =>
  `${card.issuer}, ${card.product}, son dört hane ${safeLast4(card.last4).split("").join(" ")}, ${countText(index + 1)}/${countText(count)}, bakiye ${exactText(toMinor(card.balance))}`;
export const counterText = (index: number, count: number): string => `${countText(index + 1)} / ${countText(count)}`;
export const balanceText = (card: Pick<WalletCard, "balance">): string => exactText(toMinor(card.balance));
export const transactionText = (amount: number): string => signedMinorText(toMinor(amount));
export const HINT = "Oklarla kart değiştirin. Enter kartı açar, Escape geri koyar.";

.root { container-type: inline-size; display: grid; gap: var(--space-4); width: 100%; max-width: 440px; min-width: 0; margin-inline: auto; color: var(--foreground); }
.head { display: flex; align-items: center; justify-content: space-between; gap: var(--space-3); min-height: 2rem; }
.title { margin: 0; font-family: var(--font-display); font-size: var(--text-2xl); font-weight: 500; letter-spacing: var(--tracking-display); }
.counter { color: var(--text-secondary); font-size: var(--text-sm); font-variant-numeric: tabular-nums; }
.deck { position: relative; aspect-ratio: 1.586; padding-top: calc(var(--peek-count, 3) * 10.1cqw); box-sizing: content-box; perspective: 900px; transition: padding-top var(--duration-standard, .24s) var(--ease-standard); }
.deck[data-fan] { padding-top: calc(var(--peek-count, 3) * 19.2cqw); }
.root[data-open] .deck { padding-top: 0; }
.card { position: absolute; inset: auto 0 0 0; display: block; aspect-ratio: 1.586; padding: 0; border: 0; border-radius: 5cqw; background: none; color: inherit; font: inherit; text-align: left; cursor: pointer; transform-style: preserve-3d; will-change: transform; }
.card:hover .face { box-shadow: var(--shadow-floating); }
.face { transition: box-shadow var(--duration-standard) var(--ease-standard); }
.card:focus-visible { outline: var(--focus-outline-width, 2px) solid var(--focus-outline, var(--accent)); outline-offset: 4px; }
.face { position: relative; display: grid; grid-template-rows: auto 1fr auto auto; width: 100%; height: 100%; box-sizing: border-box; padding: 3.6cqw 6cqw 5cqw; overflow: hidden; border: 1px solid var(--border-strong); border-radius: 5cqw; box-shadow: var(--shadow-raised); font-size: 3.4cqw; text-align: left; background: var(--accent); color: var(--accent-foreground); }
.face[data-material="metal"] { background: linear-gradient(135deg, var(--neutral-3), var(--neutral-5) 52%, var(--neutral-3)); color: var(--neutral-11); }
.face[data-material="black"] { background: var(--neutral-11); color: var(--neutral-0); }
.face[data-material="glass"] { background: color-mix(in oklch, var(--accent) 22%, var(--surface)); color: var(--foreground); backdrop-filter: blur(6px); }
.face[data-material="flat"] { background: var(--accent); color: var(--accent-foreground); }
.shine { position: absolute; inset: 0; background: linear-gradient(115deg, transparent 35%, color-mix(in oklch, var(--neutral-0) 22%, transparent) 50%, transparent 65%); opacity: .5; pointer-events: none; }
.top { display: flex; justify-content: space-between; align-items: baseline; font-family: var(--font-display); font-size: 4cqw; letter-spacing: var(--tracking-display); }
.chip { position: absolute; left: 6cqw; top: 30%; width: 9cqw; height: 6.6cqw; border-radius: 1.2cqw; background: linear-gradient(135deg, color-mix(in oklch, currentColor 38%, transparent), color-mix(in oklch, currentColor 14%, transparent)); border: 1px solid color-mix(in oklch, currentColor 30%, transparent); }
.top i { font-style: normal; opacity: .8; font-size: 3cqw; }
.product { align-self: end; font-size: 3cqw; opacity: .8; }
.number { font-family: var(--font-display); font-size: 5.2cqw; letter-spacing: .1em; font-variant-numeric: tabular-nums; }
.bottom { display: flex; justify-content: space-between; gap: var(--space-2); font-size: 2.8cqw; opacity: .9; }
.bottom b { font-weight: 500; font-variant-numeric: tabular-nums; }
.detail { display: grid; gap: var(--space-2); padding: var(--space-4); border: 1px solid var(--border); border-radius: var(--radius-panel); background: var(--surface); }
.balanceLabel { margin: 0; color: var(--text-secondary); font-size: var(--text-xs); }
.balance { margin: 0; font-family: var(--font-display); font-size: var(--text-4xl); font-weight: 500; letter-spacing: var(--tracking-display); font-variant-numeric: tabular-nums; }
.recent { margin: var(--space-2) 0 0; font-size: var(--text-sm); font-weight: 500; }
.list { display: grid; margin: 0; padding: 0; list-style: none; }
.list li { display: flex; align-items: center; justify-content: space-between; gap: var(--space-3); padding: var(--space-2) 0; border-bottom: 1px solid var(--border-subtle); font-size: var(--text-sm); }
.merchant { display: grid; min-width: 0; }
.merchant span { color: var(--text-muted); font-size: var(--text-xs); }
.amount { font-variant-numeric: tabular-nums; white-space: nowrap; }
.empty { margin: 0; color: var(--text-muted); font-size: var(--text-sm); }
.root[data-reduced] .shine { display: none; }
.root[data-reduced] .deck, .root[data-reduced] .face { transition: none; }
@media (prefers-reduced-motion: reduce) { .shine { display: none; } .card { will-change: auto; } }

"use client";

import { useEffect, useId, useRef, useState, type KeyboardEvent, type PointerEvent } from "react";
import { AnimatePresence, motion, useMotionValue, useTransform } from "motion/react";
import { AnimatedCounter } from "../animated-counter/animated-counter";
import { Button } from "../button/button";
import { motionTokens } from "../lib/motion-tokens";
import { srOnly, useAnnouncer } from "../lib/shop-parts";
import { useReducedMotionSafe } from "../lib/viz-utils";
import { HINT, balanceText, cardLabel, counterText, dragStep, expiryText, maskedNumber, placeOf, stepFront, transactionText, visibleCards, type CardMaterial, type CardTransaction, type WalletCard } from "./wallet-stack-format";
import styles from "./wallet-stack.module.css";

export type { CardMaterial, CardTransaction, WalletCard };

/** Birkaç ödeme ya da üyelik kartını üst üste duran bir deste olarak göstermek için kullanın: üstüne gelince deste açılır, sürükleyerek ya da oklarla dönülür, karta basınca kart öne çıkıp bakiyesini ve son hareketlerini gösterir. **Yalnız bir görünümdür: gerçek kart numarası tutmaz ve göstermez (yalnız son dört hane), gerçek ödeme yapmaz.** Kart ekleme/silme, çok sayıda hesap listesi ve kart girişi kapsam dışıdır (`wallet-card` hesap özeti içindir). En çok altı kart çizilir. */
export interface WalletStackProps {
  title?: string | undefined;
  cards: WalletCard[];
  /** Öne gelen ya da açılan kart değişince çağrılır. */
  onFrontChange?: ((card: WalletCard, index: number) => void) | undefined;
}

function Face({ card }: { card: WalletCard }) {
  return <span className={styles.face} data-material={card.material ?? "flat"} aria-hidden="true">
    <span className={styles.shine} />
    <span className={styles.chip} />
    <span className={styles.top}><b>{card.issuer}</b><i>{card.network ?? ""}</i></span>
    <span className={styles.product}>{card.product}</span>
    <span className={styles.number}>{maskedNumber(card.last4)}</span>
    <span className={styles.bottom}><span>{card.holder}</span><span>Son kullanma <b>{expiryText(card.expiry)}</b></span></span>
  </span>;
}

export function WalletStack({ title = "Kartlarım", cards: all, onFrontChange }: WalletStackProps) {
  const reduced = useReducedMotionSafe();
  const uid = useId();
  const cards = visibleCards(all);
  const [front, setFront] = useState(0);
  const [openId, setOpenId] = useState<string | null>(null);
  const [fan, setFan] = useState(false);
  const [live, announce] = useAnnouncer();
  const refs = useRef<(HTMLButtonElement | null)[]>([]);
  const tiltX = useMotionValue(0), tiltY = useMotionValue(0);
  const rotateX = useTransform(tiltY, [-1, 1], [6, -6]), rotateY = useTransform(tiltX, [-1, 1], [-8, 8]);
  const open = cards.find(card => card.id === openId) ?? null;
  const spring = reduced ? { duration: 0 } : motionTokens.spring.smooth;

  const goto = (next: number, focus = true) => {
    const target = Math.min(cards.length - 1, Math.max(0, next));
    if (target === front) return;
    setFront(target);
    onFrontChange?.(cards[target]!, target);
    announce(`${counterText(target, cards.length)}: ${cards[target]!.issuer}, ${cards[target]!.product}`);
    if (focus) requestAnimationFrame(() => refs.current[target]?.focus());
  };
  const openCard = (index: number) => {
    setOpenId(cards[index]!.id); setFront(index);
    announce(`${cards[index]!.issuer}, ${cards[index]!.product} açıldı. Bakiye ${balanceText(cards[index]!)}.`);
  };
  const close = () => {
    const index = front;
    setOpenId(null);
    announce("Tüm kartlar gösteriliyor.");
    requestAnimationFrame(() => refs.current[index]?.focus());
  };
  const key = (event: KeyboardEvent, index: number) => {
    if (event.key === "Escape" && open) { event.preventDefault(); close(); return; }
    const next = stepFront(event.key, index, cards.length);
    if (next !== index || ["ArrowDown", "ArrowRight", "ArrowUp", "ArrowLeft", "Home", "End"].includes(event.key)) {
      event.preventDefault();
      if (open) { setOpenId(cards[next]!.id); setFront(next); onFrontChange?.(cards[next]!, next); announce(`${cards[next]!.issuer}, ${cards[next]!.product} açıldı.`); requestAnimationFrame(() => refs.current[next]?.focus()); }
      else goto(next);
    }
  };
  const move = (event: PointerEvent<HTMLElement>) => {
    if (event.pointerType !== "mouse" || reduced) return;
    const rect = event.currentTarget.getBoundingClientRect();
    tiltX.set(((event.clientX - rect.left) / rect.width) * 2 - 1); tiltY.set(((event.clientY - rect.top) / rect.height) * 2 - 1);
  };
  useEffect(() => { if (cards.length && front > cards.length - 1) setFront(cards.length - 1); }, [cards.length, front]);

  if (!cards.length) return null;
  return <section className={styles.root} aria-label={title} data-open={open ? "" : undefined} data-reduced={reduced || undefined}>
    <header className={styles.head}>
      <h2 className={styles.title}>{title}</h2>
      {open ? <Button size="sm" variant="secondary" onClick={close}>Tüm kartlar</Button> : <span className={styles.counter} aria-hidden="true">{counterText(front, cards.length)}</span>}
    </header>
    <p id={`${uid}-hint`} className={srOnly}>{HINT}</p>
    <div className={styles.deck} data-fan={(fan && !open && !reduced) || undefined} role="group" aria-label={`${title}: ${cards.length} kart`} aria-describedby={`${uid}-hint`}
      style={{ ["--peek-count" as string]: open ? 0 : Math.min(3, cards.length - 1 - front) }}
      onPointerEnter={event => { if (event.pointerType === "mouse") setFan(true); }} onPointerLeave={() => { setFan(false); tiltX.set(0); tiltY.set(0); }}>
      {cards.map((card, index) => {
        const pos = index - front;
        const place = open ? (pos === 0 ? { y: 0, scale: 1, opacity: 1, hidden: false } : { y: pos < 0 ? 1.15 : -.04, scale: .94, opacity: 0, hidden: true }) : placeOf(pos, fan && !reduced ? 1 : 0, .16);
        const isFront = pos === 0;
        return <motion.button key={card.id} ref={node => { refs.current[index] = node; }} type="button" className={styles.card} style={{ zIndex: cards.length - index, rotateX: isFront && !open ? rotateX : 0, rotateY: isFront && !open ? rotateY : 0, touchAction: "pan-x" }}
          tabIndex={isFront ? 0 : -1} aria-hidden={place.hidden || !isFront || undefined} aria-expanded={isFront ? !!open : undefined} aria-label={cardLabel(card, index, cards.length)}
          animate={{ y: `${place.y * 100}%`, scale: place.scale, opacity: place.opacity }} transition={spring}
          drag={isFront && !reduced ? "y" : false} dragConstraints={{ top: 0, bottom: 0 }} dragElastic={.35}
          onDragEnd={(_, info) => { if (open) { if (info.offset.y > 80) close(); return; } const step = dragStep(info.offset.y, info.velocity.y); if (step) goto(front + step); }}
          onClick={() => { if (isFront && open) close(); else openCard(index); }} onKeyDown={event => key(event, index)} onPointerMove={isFront ? move : undefined}>
          <Face card={card} />
        </motion.button>;
      })}
    </div>
    <AnimatePresence initial={false}>
      {open && <motion.section key={open.id} className={styles.detail} aria-label={`${open.issuer} ${open.product} ayrıntısı`} initial={reduced ? false : { opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} transition={reduced ? { duration: 0 } : { duration: motionTokens.duration.standard }}>
        <p className={styles.balanceLabel}>Kullanılabilir</p>
        <p className={styles.balance} aria-label={`Kullanılabilir bakiye ${balanceText(open)}`}><AnimatedCounter value={open.balance} decimals={2} prefix="₺" /></p>
        <h3 className={styles.recent}>Son hareketler</h3>
        {open.transactions.length === 0 ? <p className={styles.empty}>Henüz hareket yok</p>
          : <ul className={styles.list}>{open.transactions.slice(0, 3).map((item, at) => <motion.li key={item.id} initial={reduced ? false : { opacity: 0, y: 6 }} animate={{ opacity: 1, y: 0 }} transition={reduced ? { duration: 0 } : { delay: .12 + at * motionTokens.stagger.line, duration: motionTokens.duration.standard }}>
            <span className={styles.merchant}><b>{item.merchant}</b>{item.detail && <span>{item.detail}</span>}</span><span className={styles.amount}>{transactionText(item.amount)}</span>
          </motion.li>)}</ul>}
      </motion.section>}
    </AnimatePresence>
    {live}
  </section>;
}

export default WalletStack;
